//! The generated bytes have to be git's bytes, on assertion alone they are not.
//!
//! `fathom-fixtures` writes loose objects, loose refs and a `DIRC` index itself, and never asks `git` to
//! do anything (see `src/git.rs` for why). That is only defensible if the real binary agrees, so this file
//! asks it twice: first that `git` can read, verify and find clean a generated repository, and second that
//! a commit written by `fathom-fixtures` and the same commit written by `git commit` have *the same id* —
//! which is the one test that would fail the day this crate's encoder drifts.
//!
//! `git` is a fixture here, not a dependency: every test in the crate proper works without it, and these
//! skip (loudly, by printing) when it is absent.
#![allow(clippy::unwrap_used, clippy::expect_used)]

mod support;

use fathom_fixtures::git::{CommitSpec, File, GitDir};
use fathom_fixtures::policy::{HUMAN_REVIEWER, PI};
use std::collections::BTreeMap;

use support::{git, git_available, git_with_env, scratch};

/// The files every generated repository in this file contains, in corpus order.
fn files() -> BTreeMap<String, File> {
    let mut files = BTreeMap::new();
    files.insert(
        "Cargo.toml".to_owned(),
        File::text("[package]\nname = \"lumen\"\nversion = \"0.1.0\"\nedition = \"2024\"\n"),
    );
    files.insert(
        "src/lib.rs".to_owned(),
        File::text("pub fn greet(name: &str) -> String {\n    format!(\"hi {name}\")\n}\n"),
    );
    files.insert(
        "src/nested/deep/mod.rs".to_owned(),
        File::text("pub const DEEP: u32 = 7;\n"),
    );
    files
}

const MESSAGE: &str =
    "feat: greet someone\n\nA greeting, so the fixture has a function to rename later.";

#[test]
fn a_commit_written_here_has_git_id() {
    if !git_available() {
        eprintln!("skipping: no git binary");
        return;
    }
    let mine = scratch("mine");
    let theirs = scratch("theirs");

    let mut dir = GitDir::create(
        &mine,
        &mine.join(".git"),
        "refs/heads/main",
        &[String::from("bare = false")],
    )
    .expect("create");
    let tree = dir.tree(&files()).expect("tree");
    let spec = CommitSpec {
        tree: tree.clone(),
        parents: Vec::new(),
        identity: &PI,
        at: 1_735_689_600,
        message: MESSAGE.to_owned(),
    };
    let sha = dir.commit(&spec).expect("commit");
    dir.set_ref("refs/heads/main", &sha).expect("ref");
    dir.checkout(&files(), spec.at).expect("checkout");

    // The same commit, from `git` itself: same tree content, same signature, same message bytes.
    git(&theirs, &["init", "-q", "--initial-branch=main"]);
    for (path, file) in files() {
        let joined = theirs.join(&path);
        std::fs::create_dir_all(joined.parent().unwrap()).unwrap();
        std::fs::write(&joined, &file.blob).unwrap();
    }
    git(&theirs, &["add", "-A"]);
    let env = [
        ("GIT_AUTHOR_NAME", PI.author.name),
        ("GIT_AUTHOR_EMAIL", PI.author.email),
        ("GIT_COMMITTER_NAME", PI.author.name),
        ("GIT_COMMITTER_EMAIL", PI.author.email),
        ("GIT_AUTHOR_DATE", "@1735689600 +0000"),
        ("GIT_COMMITTER_DATE", "@1735689600 +0000"),
    ];
    git_with_env(&theirs, &["commit", "-q", "-m", MESSAGE], &env);
    let their_sha = git(&theirs, &["rev-parse", "HEAD"]);
    assert_eq!(
        their_sha, sha,
        "`git commit` and `fathom-fixtures` disagree about the same commit"
    );
    assert_eq!(
        git(&theirs, &["rev-parse", "HEAD^{tree}"]),
        tree,
        "and about its tree"
    );
}

#[test]
fn git_reads_a_generated_repository_and_find_it_clean() {
    if !git_available() {
        eprintln!("skipping: no git binary");
        return;
    }
    let dir = scratch("clean");
    let mut repo = GitDir::create(&dir, &dir.join(".git"), "refs/heads/main", &[String::new()])
        .expect("create");
    let first_files = files();
    let tree = repo.tree(&first_files).expect("tree");
    let first = repo
        .commit(&CommitSpec {
            tree,
            parents: Vec::new(),
            identity: &PI,
            at: 1_735_689_600,
            message: MESSAGE.to_owned(),
        })
        .expect("commit");
    repo.set_ref("refs/heads/main", &first).expect("ref");
    repo.checkout(&first_files, 1_735_689_600)
        .expect("checkout");

    // A second commit that only reformats, so `git diff` has something to say and the index has two rows.
    let mut second_files = first_files.clone();
    second_files.insert(
        "src/lib.rs".to_owned(),
        File::text("pub fn greet(name: &str) -> String {\n  format!(\"hi {name}\")\n}\n"),
    );
    let tree = repo.tree(&second_files).expect("tree");
    let second = repo
        .commit(&CommitSpec {
            tree,
            parents: vec![first.clone()],
            identity: &HUMAN_REVIEWER,
            at: 1_735_689_660,
            message: "style: reindent".to_owned(),
        })
        .expect("commit");
    repo.set_ref("refs/heads/main", &second).expect("ref");
    repo.checkout(&second_files, 1_735_689_660)
        .expect("checkout");

    assert_eq!(git(&dir, &["rev-parse", "HEAD"]), second);
    assert_eq!(git(&dir, &["rev-parse", "HEAD~1"]), first);
    assert_eq!(
        git(&dir, &["log", "--format=%s", "--reverse"]),
        "feat: greet someone\nstyle: reindent"
    );
    assert_eq!(
        git(&dir, &["ls-files"]),
        "Cargo.toml\nsrc/lib.rs\nsrc/nested/deep/mod.rs"
    );
    git(&dir, &["fsck", "--strict"]);
    assert_eq!(
        git(&dir, &["status", "--porcelain"]),
        "",
        "a generated fixture must not look dirty: the index has to match the work tree"
    );
    // The excluded sidecars are the only thing in the work tree that is not tracked, and they are excluded
    // by `.git/info/exclude`, which the generator wrote.
    std::fs::write(dir.join("fixture.json"), "{}\n").expect("write sidecar");
    std::fs::create_dir_all(dir.join(".fathom")).expect("sidecar dir");
    std::fs::write(dir.join(".fathom").join("events.jsonl"), "{}\n").expect("events");
    assert_eq!(
        git(&dir, &["status", "--porcelain"]),
        "",
        "the sidecars must be excluded, not merely untracked"
    );
    assert_eq!(
        git(&dir, &["cat-file", "-p", &first])
            .lines()
            .next()
            .unwrap_or_default()
            .split_whitespace()
            .nth(1)
            .unwrap_or_default()
            .len(),
        40,
        "the commit object parses and names a tree"
    );
}
